        UNION SELECT '20238','NOVA LAKE-CPU-8P-16E','NOVA LAKE-CPU-8P-16E'


        -- =====================================================
        -- POPULATE TEST SCENARIO 3 DATA
        -- Get attribute names and check deletion status
        -- =====================================================
        
        -- Get attribute names for all test values
        UPDATE tgt
        SET tgt.att_nme = d.att_nme
        FROM #Deleted tgt
        LEFT JOIN dbo.uda_definition d ON d.att_idn = tgt.att_idn 
        WHERE tgt.att_idn IS NOT NULL;

        -- Get actual values from validation list (if they exist)
        UPDATE tgt
        SET tgt.val_txt = src.val_txt,tgt.val_dsc = src.dsc
        FROM #Deleted tgt
        LEFT JOIN dbo.uda_validation_list src ON src.att_idn = tgt.att_idn AND src.val_txt = tgt.expected_val_txt
        WHERE tgt.att_idn IS NOT NULL;

        -- Check if values are properly marked as deleted (curr_actv_ind = 'N')
        UPDATE tgt
        SET tgt.assert = 'PASS',tgt.result = 'Marked as Deleted'
        FROM #Deleted tgt
        JOIN dbo.uda_validation_list src 
        ON src.val_txt = tgt.expected_val_txt
        AND src.att_idn = tgt.att_idn  
        AND src.curr_actv_ind = 'N';  -- Key check: is it marked as inactive/deleted?

        -- =====================================================
        -- RETURN TEST RESULTS
        -- Three result sets for the three test scenarios
        -- =====================================================
        
        -- Result Set 1: Value-Description pair validation results
        SELECT att_idn, att_nme, expected_val_txt, val_txt, expected_val_dsc, val_dsc, assert, result
        FROM #Updated;
        
        -- Result Set 2: Standalone value existence validation results
        SELECT att_idn, att_nme, expected_val_txt, val_txt, expected_val_dsc, val_dsc,assert, result
        FROM #Inserted;
        
        -- Result Set 3: Deleted value validation results
        SELECT att_idn, att_nme, expected_val_txt, val_txt, expected_val_dsc, val_dsc,assert, result
        FROM #Deleted;

    END TRY
    BEGIN CATCH
        -- =====================================================
        -- ERROR HANDLING
        -- Provide detailed error information for debugging
        -- =====================================================
        PRINT 'Error occurred during execution.';
        PRINT 'Message     : ' + ERROR_MESSAGE();
        PRINT 'Line        : ' + CAST(ERROR_LINE() AS VARCHAR);
    END CATCH
